using System;
using System.Globalization;
using EmberBastion;
class CoreChecks {
 static int passed;
 static void Check(bool ok,string message){if(!ok)throw new Exception(message);passed++;Console.WriteLine("PASS "+message);}
 static void Advance(Battle b,double seconds){for(int i=0;i<(int)(seconds*60);i++)b.Step(1.0/60);}
 static int Main(string[] args){try{Run(args);return 0;}catch(Exception e){Console.Error.WriteLine("FAIL "+e.Message);return 1;}}
 static void MixedTrace(string mode){
  bool frostOnly=mode=="frost-waves",aggregate=mode.StartsWith("aggregate-"),strong=mode.StartsWith("strong-");
  int field=mode.EndsWith("forest")?1:mode.EndsWith("pass")?2:0,period=(mode=="frost-waves"||mode=="mixed-frost")?600:60;
  for(int wave=1;wave<=Balance.Fields[field].Waves.Length;wave++)for(int branch=0;branch<3;branch++){
   var t=new Battle(42,field);t.Wave=wave-1;t.Gold=5000;
   for(int slot=0;slot<4;slot++){t.Place(frostOnly?3:slot,slot);if(branch>0){t.Upgrade(slot);t.UpgradeBranch(slot,branch);if(!frostOnly&&(slot==1||slot==3))t.SetPriority(slot,strong?1:2);}}t.Start();
   for(int n=1;n<=7200;n++){t.Step(1.0/60);if(n%period!=0)continue;var e=t.Enemies.Count>0?t.Enemies[0]:null;
    string row=wave+","+branch+","+n+","+t.Phase+","+t.Gold+","+t.HP+","+t.Kills+","+t.Enemies.Count+","+t.Pending+","+t.Shots.Count+","+(e!=null?e.Travel.ToString("R"):"-")+","+(e!=null?e.HP.ToString("R"):"-")+","+(e!=null?e.SlowTime.ToString("R"):"-")+","+(e!=null?e.FreezeTime.ToString("R"):"-");
    if(aggregate)row+=","+System.Linq.Enumerable.Sum(t.Enemies,z=>z.HP).ToString("R")+","+System.Linq.Enumerable.Sum(t.Enemies,z=>z.Travel).ToString("R")+","+System.Linq.Enumerable.Sum(t.Enemies,z=>z.SlowTime).ToString("R")+","+System.Linq.Enumerable.Sum(t.Enemies,z=>z.FreezeTime).ToString("R");Console.WriteLine(row);
   }
  }
 }
